// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type SinglePointInfographicProps = Record<string, any>;

const SinglePointInfographic: React.FC<SinglePointInfographicProps> = ({
  backgroundColor = "#F8F9FA",
  transparentBackground = false,
  durationInSeconds = 10,
  title = "A Single Point of Failure",
  description = "It only takes one compromised employee account for a cybercriminal to gain access to an entire company's secure network and sensitive data.",
  entryPointText = "Compromised Entry Point",
  accentColor = "#E63946",
  textColor = "#1D3557",
  safeColor = "#A8B2C1",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors for background color
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Layout Dimensions
  const padding = width * 0.06;
  const contentWidth = width * 0.65;

  // Animations: Text Entrance
  const titleSpring = spring({
    frame: frame - 10,
    fps,
    config: { damping: 14, stiffness: 100 },
  });
  const titleY = interpolate(titleSpring, [0, 1], [40, 0]);
  const titleOpacity = interpolate(titleSpring, [0, 1], [0, 1]);

  const descSpring = spring({
    frame: frame - 20,
    fps,
    config: { damping: 14, stiffness: 100 },
  });
  const descY = interpolate(descSpring, [0, 1], [40, 0]);
  const descOpacity = interpolate(descSpring, [0, 1], [0, 1]);

  // Grid Visualization (Network spread)
  const rows = 4;
  const cols = 8;
  const totalEmployees = rows * cols;
  const infectedIndex = 11; // Index of the entry point employee
  const infectedRow = Math.floor(infectedIndex / cols);
  const infectedCol = infectedIndex % cols;

  const dots = Array.from({ length: totalEmployees }).map((_, i) => {
    const r = Math.floor(i / cols);
    const c = i % cols;
    // Calculate distance from the initial compromised node
    const distance = Math.sqrt(
      Math.pow(r - infectedRow, 2) + Math.pow(c - infectedCol, 2)
    );

    // Spread timing: start at frame 60, spread outward
    const spreadDelay = 60 + distance * 8;
    const spreadSpring = spring({
      frame: frame - spreadDelay,
      fps,
      config: { damping: 12 },
    });

    const isEntryPoint = i === infectedIndex;
    
    // Entry point turns red earlier (frame 40)
    const entryDelay = isEntryPoint ? 40 : spreadDelay;
    const colorSpring = spring({
      frame: frame - entryDelay,
      fps,
      config: { damping: 20 },
    });

    const scale = interpolate(colorSpring, [0, 0.5, 1], [1, 1.3, 1], {
      extrapolateRight: "clamp",
    });
    
    const dotOpacity = interpolate(
      frame - 25, // Fixed cascade for initial entrance without randomness
      [0, 15],
      [0, 1],
      { extrapolateRight: "clamp" }
    );

    return {
      id: i,
      scale,
      opacity: dotOpacity,
      isCompromised: colorSpring > 0.1,
      isEntryPoint,
      colorSpring,
    };
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        display: "flex",
        flexDirection: "column",
        padding: `${padding}px`,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* Centered Content Column */}
      <div
        style={{
          width: contentWidth,
          display: "flex",
          flexDirection: "column",
          gap: "50px",
        }}
      >
        <div style={{ display: "flex", flexDirection: "column", gap: "20px", alignItems: "center", textAlign: "center" }}>
          <h1
            style={{
              fontSize: width * 0.038,
              fontWeight: 800,
              color: textColor,
              lineHeight: 1.1,
              margin: 0,
              opacity: titleOpacity,
              transform: `translateY(${titleY}px)`,
              letterSpacing: "-0.02em",
            }}
          >
            {title}
          </h1>
          <p
            style={{
              fontSize: width * 0.016,
              color: textColor,
              opacity: descOpacity,
              transform: `translateY(${descY}px)`,
              lineHeight: 1.5,
              margin: 0,
              fontWeight: 400,
            }}
          >
            {description}
          </p>
        </div>

        {/* Network Spread Visualization */}
        <div
          style={{
            display: "grid",
            gridTemplateColumns: `repeat(${cols}, 1fr)`,
            gap: "20px",
            width: "100%",
            position: "relative",
            padding: "30px",
            backgroundColor: "rgba(0,0,0,0.03)",
            borderRadius: "24px",
            border: "1px solid rgba(0,0,0,0.05)",
          }}
        >
          {dots.map((dot) => (
            <div
              key={dot.id}
              style={{
                width: "100%",
                aspectRatio: "1/1",
                position: "relative",
                opacity: dot.opacity,
              }}
            >
              {/* Base Safe Node */}
              <div
                style={{
                  position: "absolute",
                  inset: "10%",
                  backgroundColor: safeColor,
                  borderRadius: "50%",
                  transform: `scale(${dot.scale})`,
                }}
              />
              {/* Compromised Node Overlay */}
              <div
                style={{
                  position: "absolute",
                  inset: "10%",
                  backgroundColor: accentColor,
                  borderRadius: "50%",
                  opacity: dot.colorSpring,
                  transform: `scale(${dot.scale})`,
                  boxShadow: `0 0 15px ${accentColor}80`,
                }}
              />
            </div>
          ))}

          {/* Entry Point Label */}
          {(() => {
            const labelSpring = spring({
              frame: frame - 45,
              fps,
              config: { damping: 12 },
            });
            const labelOpacity = interpolate(labelSpring, [0, 1], [0, 1]);
            const labelY = interpolate(labelSpring, [0, 1], [20, 0]);

            return (
              <div
                style={{
                  position: "absolute",
                  left: `${(infectedCol / cols) * 100 + (100 / cols) * 0.5}%`,
                  top: `${(infectedRow / rows) * 100 - 15}%`,
                  transform: `translate(-50%, -100%) translateY(${labelY}px)`,
                  opacity: labelOpacity,
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  gap: "8px",
                  pointerEvents: "none",
                }}
              >
                <div
                  style={{
                    backgroundColor: accentColor,
                    color: "#fff",
                    padding: "8px 16px",
                    borderRadius: "20px",
                    fontSize: width * 0.012,
                    fontWeight: 700,
                    whiteSpace: "nowrap",
                    boxShadow: "0 8px 16px rgba(0,0,0,0.15)",
                  }}
                >
                  {entryPointText}
                </div>
                {/* Arrow pointing down */}
                <svg
                  width="18"
                  height="18"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke={accentColor}
                  strokeWidth="3"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <line x1="12" y1="2" x2="12" y2="22"></line>
                  <polyline points="19 15 12 22 5 15"></polyline>
                </svg>
              </div>
            );
          })()}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default SinglePointInfographic;